  if(markdown.length){const prefix=line.slice(0,markdown[0].index).replace(/^[-*]\s*/,'').replace(/[:：]\s*$/,'').trim();markdown.forEach((match,index)=>entries.push({name:index===0?prefix:'',url:match[2]}));continue}
